export class CliError extends Error {
  constructor(message, code) {
    super(message)
    this.code = code
  }
}

/** A dependency cycle, reported with the names that form it, first-to-repeat. */
export class CycleError extends CliError {
  constructor(names) {
    super(`cycle: ${names.join(' -> ')}`, 3)
    this.names = names
  }
}
"}

