{"file_path":"src/parse.js","content":"import { CliError } from './errors.js'

const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

/**
 * Parses a build graph from raw input text into a task cost map and a
 * dependency adjacency map, enforcing every syntactic and referential rule
 * the format defines.
 */
export function parseGraph(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const tasks = new Map()
  const depEntries = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) throw new CliError(`line ${lineNo}: expected task <name> <cost>`, 2)
      const [, name, costStr] = words
      if (!NAME_RE.test(name)) throw new CliError(`line ${lineNo}: invalid task name ${name}`, 2)
      if (!COST_RE.test(costStr)) throw new CliError(`line ${lineNo}: cost must be a non-negative integer`, 2)
      if (tasks.has(name)) throw new CliError(`line ${lineNo}: task ${name} is declared twice`, 2)
      tasks.set(name, parseInt(costStr, 10))
    } else if (directive === 'dep') {
      if (words.length < 3) throw new CliError(`line ${lineNo}: expected dep <name> <dependency>...`, 2)
      const from = words[1]
      const tos = words.slice(2)
      for (const name of [from, ...tos]) {
        if (!NAME_RE.test(name)) throw new CliError(`line ${lineNo}: invalid task name ${name}`, 2)
      }
      depEntries.push({ from, tos })
    } else {
      throw new CliError(`line ${lineNo}: unknown directive ${directive}`, 2)
    }
  }

  for (const entry of depEntries) {
    if (!tasks.has(entry.from)) throw new CliError(`unknown task ${entry.from}`, 2)
    for (const to of entry.tos) {
      if (!tasks.has(to)) throw new CliError(`unknown task ${to}`, 2)
    }
  }

  const adjacency = new Map()
  for (const name of tasks.keys()) adjacency.set(name, new Set())
  for (const entry of depEntries) {
    const set = adjacency.get(entry.from)
    for (const to of entry.tos) set.add(to)
  }

  return { tasks, adjacency }
}
"}

