{"file_path":"src/cycle.js","content":"import { CycleError } from './errors.js'

/**
 * Finds the first dependency cycle a depth-first search encounters when it
 * starts from each task in ascending name order and walks each task's
 * dependencies in ascending name order. Returns the cycle as a name array
 * ending with a repeat of its first name, or null when the graph is acyclic.
 */
export function findCycle(tasks, adjacency) {
  const names = [...tasks.keys()].sort()
  const state = new Map(names.map((name) => [name, 0])) // 0 unvisited, 1 in-stack, 2 done
  const path = []

  for (const start of names) {
    if (state.get(start) !== 0) continue

    const frames = [{ node: start, deps: [...adjacency.get(start)].sort(), index: 0 }]
    state.set(start, 1)
    path.push(start)

    while (frames.length > 0) {
      const frame = frames[frames.length - 1]
      if (frame.index >= frame.deps.length) {
        state.set(frame.node, 2)
        path.pop()
        frames.pop()
        continue
      }
      const dep = frame.deps[frame.index++]
      const depState = state.get(dep)
      if (depState === 1) {
        const start = path.indexOf(dep)
        return path.slice(start).concat(dep)
      }
      if (depState === 0) {
        state.set(dep, 1)
        path.push(dep)
        frames.push({ node: dep, deps: [...adjacency.get(dep)].sort(), index: 0 })
      }
    }
  }

  return null
}

/** Throws a CycleError when the graph contains a dependency cycle. */
export function assertAcyclic(tasks, adjacency) {
  const cycle = findCycle(tasks, adjacency)
  if (cycle) throw new CycleError(cycle)
}
"}

