{"file_path":"src/schedule.js","content":"/**
 * Returns task names ordered so that every dependency of a task precedes it
 * (an arbitrary but deterministic topological order). Assumes the graph is
 * already known to be acyclic.
 */
export function topoOrder(tasks, adjacency) {
  const names = [...tasks.keys()].sort()
  const visited = new Set()
  const order = []

  for (const start of names) {
    if (visited.has(start)) continue
    const frames = [{ node: start, deps: [...adjacency.get(start)].sort(), index: 0 }]
    visited.add(start)

    while (frames.length > 0) {
      const frame = frames[frames.length - 1]
      if (frame.index >= frame.deps.length) {
        order.push(frame.node)
        frames.pop()
        continue
      }
      const dep = frame.deps[frame.index++]
      if (!visited.has(dep)) {
        visited.add(dep)
        frames.push({ node: dep, deps: [...adjacency.get(dep)].sort(), index: 0 })
      }
    }
  }

  return order
}

/**
 * Computes each task's start, finish and wave depth under unlimited
 * workers: a task starts when its slowest dependency finishes (0 with no
 * dependencies) and its depth is one past its deepest dependency's depth.
 */
export function computeTimings(tasks, adjacency, order) {
  const start = new Map()
  const finish = new Map()
  const depth = new Map()

  for (const name of order) {
    const deps = adjacency.get(name)
    let s = 0
    let d = 0
    for (const dep of deps) {
      if (finish.get(dep) > s) s = finish.get(dep)
      if (depth.get(dep) + 1 > d) d = depth.get(dep) + 1
    }
    start.set(name, s)
    finish.set(name, s + tasks.get(name))
    depth.set(name, d)
  }

  return { start, finish, depth }
}

/**
 * Computes each task's scheduling priority: the cost of the longest chain
 * of costs starting at the task and following its dependents down to a
 * task nothing depends on.
 */
export function computePriority(tasks, adjacency, order) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, new Set())
  for (const [name, deps] of adjacency) {
    for (const dep of deps) dependents.get(dep).add(name)
  }

  const priority = new Map()
  for (let i = order.length - 1; i >= 0; i--) {
    const name = order[i]
    let best = 0
    for (const dependent of dependents.get(name)) {
      if (priority.get(dependent) > best) best = priority.get(dependent)
    }
    priority.set(name, tasks.get(name) + best)
  }

  return priority
}

/** Groups task names by wave depth, ascending name within each wave. */
export function groupWaves(tasks, depth) {
  const waves = []
  for (const name of [...tasks.keys()].sort()) {
    const d = depth.get(name)
    if (!waves[d]) waves[d] = []
    waves[d].push(name)
  }
  return waves
}

/** The makespan with unlimited workers: the greatest finish, or 0 with no tasks. */
export function totalOf(finish) {
  let total = 0
  for (const f of finish.values()) if (f > total) total = f
  return total
}
"}

