/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { CliError } from './errors.js'
import { parseGraph } from './parse.js'
import { assertAcyclic } from './cycle.js'
import { computePriority, computeTimings, groupWaves, topoOrder, totalOf } from './schedule.js'
import { pack } from './pack.js'

const USAGE = 'usage: cli.js waves|explain|pack <workers>'
const WORKERS_RE = /^(?:[1-9][0-9]*)$/

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_RE.test(argv[1])) throw new CliError('workers must be a positive integer', 2)
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  throw new CliError(USAGE, 2)
}

function readStdin() {
  return new Promise((resolve, reject) => {
    const chunks = []
    process.stdin.on('data', (chunk) => chunks.push(chunk))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

function renderWaves(tasks, depth, total) {
  const lines = []
  const waves = groupWaves(tasks, depth)
  waves.forEach((names, k) => lines.push(`wave ${k}: ${names.join(' ')}`))
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

function renderExplain(tasks, start, finish, depth, total) {
  const lines = []
  for (const name of [...tasks.keys()].sort()) {
    lines.push(`${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}`)
  }
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

function renderPack(workerCount, tasks, adjacency) {
  const { workers, makespan } = pack(tasks, adjacency, workerCount)
  const lines = workers.map((w, i) => {
    const entries = w.log.map((e) => ` ${e.name}@${e.start}-${e.finish}`).join('')
    return `worker ${i}:${entries}`
  })
  lines.push(`makespan ${makespan}`)
  return lines.join('\n') + '\n'
}

async function main() {
  const { mode, workers } = parseArgs(process.argv.slice(2))
  const text = await readStdin()
  const { tasks, adjacency } = parseGraph(text)
  assertAcyclic(tasks, adjacency)

  const order = topoOrder(tasks, adjacency)
  const { start, finish, depth } = computeTimings(tasks, adjacency, order)
  const total = totalOf(finish)

  let output
  if (mode === 'waves') output = renderWaves(tasks, depth, total)
  else if (mode === 'explain') output = renderExplain(tasks, start, finish, depth, total)
  else output = renderPack(workers, tasks, adjacency)

  process.stdout.write(output)
}

main().catch((err) => {
  if (err instanceof CliError) {
    process.stderr.write(`error: ${err.message}\n`)
    process.exit(err.code)
  }
  throw err
})
"}

